#include <algorithm>
#include <iostream>
#include <vector>

int searchInsert(const std::vector<int>& nums, int target) {
    auto it = std::lower_bound(nums.begin(), nums.end(), target);
    return static_cast<int>(it - nums.begin());
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> nums(n);
