import { readFileSync } from "node:fs";

const input = readFileSync(0, "utf8");

function searchInsert(nums: number[], target: number): number {
  let lo = 0;
  let hi = nums.length;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    const value = nums[mid];
    if (value !== undefined && value < target) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }
  return lo;
}

